
-- Enterprise Service Management Platform (ESMP)
-- PostgreSQL 15+ | Synthetic training dataset | No real personal data
BEGIN;

DROP SCHEMA IF EXISTS esmp CASCADE;
CREATE SCHEMA esmp;
SET search_path TO esmp;

CREATE TABLE companies (
  company_id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, code VARCHAR(20) UNIQUE NOT NULL
);
CREATE TABLE offices (
  office_id BIGSERIAL PRIMARY KEY, company_id BIGINT NOT NULL REFERENCES companies,
  name VARCHAR(100) NOT NULL, city VARCHAR(80) NOT NULL, country VARCHAR(80) NOT NULL, timezone VARCHAR(60) NOT NULL
);
CREATE TABLE departments (
  department_id BIGSERIAL PRIMARY KEY, company_id BIGINT NOT NULL REFERENCES companies,
  name VARCHAR(100) NOT NULL, cost_centre VARCHAR(30)
);
CREATE TABLE users (
  user_id BIGSERIAL PRIMARY KEY, employee_no VARCHAR(20) UNIQUE NOT NULL,
  first_name VARCHAR(60) NOT NULL, last_name VARCHAR(60) NOT NULL,
  email VARCHAR(160) UNIQUE NOT NULL, office_id BIGINT REFERENCES offices,
  department_id BIGINT REFERENCES departments, manager_id BIGINT REFERENCES users,
  employment_status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CHECK (employment_status IN ('ACTIVE','INACTIVE','ON_LEAVE')),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE roles (
  role_id BIGSERIAL PRIMARY KEY, role_name VARCHAR(60) UNIQUE NOT NULL, description TEXT
);
CREATE TABLE user_roles (
  user_id BIGINT REFERENCES users ON DELETE CASCADE, role_id BIGINT REFERENCES roles,
  PRIMARY KEY(user_id, role_id)
);
CREATE TABLE teams (
  team_id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, support_level SMALLINT NOT NULL CHECK(support_level BETWEEN 1 AND 3),
  manager_user_id BIGINT REFERENCES users, is_active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE team_members (
  team_id BIGINT REFERENCES teams ON DELETE CASCADE, user_id BIGINT REFERENCES users ON DELETE CASCADE,
  joined_at DATE NOT NULL, PRIMARY KEY(team_id,user_id)
);
CREATE TABLE service_categories (
  category_id BIGSERIAL PRIMARY KEY, name VARCHAR(80) UNIQUE NOT NULL
);
CREATE TABLE services (
  service_id BIGSERIAL PRIMARY KEY, category_id BIGINT REFERENCES service_categories,
  name VARCHAR(120) NOT NULL, description TEXT, owning_team_id BIGINT REFERENCES teams,
  is_active BOOLEAN NOT NULL DEFAULT TRUE
);
CREATE TABLE priorities (
  priority_id SMALLINT PRIMARY KEY, name VARCHAR(20) UNIQUE NOT NULL,
  response_minutes INTEGER NOT NULL, resolution_minutes INTEGER NOT NULL
);
CREATE TABLE ticket_statuses (
  status_id SMALLINT PRIMARY KEY, name VARCHAR(30) UNIQUE NOT NULL, is_closed BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE TABLE sla_policies (
  sla_id BIGSERIAL PRIMARY KEY, name VARCHAR(100) NOT NULL, priority_id SMALLINT REFERENCES priorities,
  service_id BIGINT REFERENCES services, business_hours_only BOOLEAN NOT NULL DEFAULT TRUE,
  response_target_minutes INTEGER NOT NULL, resolution_target_minutes INTEGER NOT NULL,
  effective_from DATE NOT NULL, effective_to DATE
);
CREATE TABLE assets (
  asset_id BIGSERIAL PRIMARY KEY, asset_tag VARCHAR(30) UNIQUE NOT NULL,
  asset_type VARCHAR(40) NOT NULL, manufacturer VARCHAR(60), model VARCHAR(80),
  serial_number VARCHAR(80) UNIQUE, purchase_date DATE, warranty_end DATE,
  office_id BIGINT REFERENCES offices, assigned_user_id BIGINT REFERENCES users,
  asset_status VARCHAR(20) NOT NULL CHECK(asset_status IN ('IN_STOCK','ASSIGNED','REPAIR','RETIRED','LOST')),
  purchase_cost NUMERIC(12,2), created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE incidents (
  incident_id BIGSERIAL PRIMARY KEY, ticket_no VARCHAR(20) UNIQUE NOT NULL,
  title VARCHAR(200) NOT NULL, description TEXT NOT NULL,
  requester_id BIGINT NOT NULL REFERENCES users, service_id BIGINT REFERENCES services,
  asset_id BIGINT REFERENCES assets, priority_id SMALLINT NOT NULL REFERENCES priorities,
  status_id SMALLINT NOT NULL REFERENCES ticket_statuses, assigned_team_id BIGINT REFERENCES teams,
  assigned_user_id BIGINT REFERENCES users, sla_id BIGINT REFERENCES sla_policies,
  channel VARCHAR(20) NOT NULL CHECK(channel IN ('PORTAL','EMAIL','PHONE','CHAT','MONITORING')),
  created_at TIMESTAMPTZ NOT NULL, first_response_at TIMESTAMPTZ, resolved_at TIMESTAMPTZ,
  closed_at TIMESTAMPTZ, due_at TIMESTAMPTZ, reopened_count INTEGER NOT NULL DEFAULT 0,
  satisfaction_score SMALLINT CHECK(satisfaction_score BETWEEN 1 AND 5)
);
CREATE TABLE incident_comments (
  comment_id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents ON DELETE CASCADE,
  author_id BIGINT NOT NULL REFERENCES users, body TEXT NOT NULL,
  is_internal BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE worklogs (
  worklog_id BIGSERIAL PRIMARY KEY, incident_id BIGINT NOT NULL REFERENCES incidents ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES users, minutes_spent INTEGER NOT NULL CHECK(minutes_spent > 0),
  work_description TEXT NOT NULL, logged_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE service_requests (
  request_id BIGSERIAL PRIMARY KEY, request_no VARCHAR(20) UNIQUE NOT NULL,
  requester_id BIGINT NOT NULL REFERENCES users, service_id BIGINT REFERENCES services,
  title VARCHAR(200) NOT NULL, details TEXT, status VARCHAR(25) NOT NULL,
  requested_at TIMESTAMPTZ NOT NULL, fulfilled_at TIMESTAMPTZ, estimated_cost NUMERIC(12,2)
);
CREATE TABLE approvals (
  approval_id BIGSERIAL PRIMARY KEY, request_id BIGINT REFERENCES service_requests,
  change_id BIGINT, approver_id BIGINT NOT NULL REFERENCES users,
  decision VARCHAR(20) NOT NULL CHECK(decision IN ('PENDING','APPROVED','REJECTED')),
  comments TEXT, decided_at TIMESTAMPTZ
);
CREATE TABLE problems (
  problem_id BIGSERIAL PRIMARY KEY, problem_no VARCHAR(20) UNIQUE NOT NULL,
  title VARCHAR(200) NOT NULL, description TEXT, status VARCHAR(25) NOT NULL,
  root_cause TEXT, workaround TEXT, known_error BOOLEAN NOT NULL DEFAULT FALSE,
  owner_team_id BIGINT REFERENCES teams, created_at TIMESTAMPTZ NOT NULL, resolved_at TIMESTAMPTZ
);
CREATE TABLE incident_problem_links (
  incident_id BIGINT REFERENCES incidents ON DELETE CASCADE,
  problem_id BIGINT REFERENCES problems ON DELETE CASCADE,
  PRIMARY KEY(incident_id,problem_id)
);
CREATE TABLE change_requests (
  change_id BIGSERIAL PRIMARY KEY, change_no VARCHAR(20) UNIQUE NOT NULL,
  title VARCHAR(200) NOT NULL, description TEXT NOT NULL,
  change_type VARCHAR(20) NOT NULL CHECK(change_type IN ('STANDARD','NORMAL','EMERGENCY')),
  status VARCHAR(25) NOT NULL, requester_id BIGINT REFERENCES users,
  owner_team_id BIGINT REFERENCES teams, planned_start TIMESTAMPTZ, planned_end TIMESTAMPTZ,
  actual_start TIMESTAMPTZ, actual_end TIMESTAMPTZ, risk_level VARCHAR(15),
  rollback_plan TEXT, created_at TIMESTAMPTZ NOT NULL
);
CREATE TABLE knowledge_articles (
  article_id BIGSERIAL PRIMARY KEY, title VARCHAR(200) NOT NULL, body TEXT NOT NULL,
  category_id BIGINT REFERENCES service_categories, author_id BIGINT REFERENCES users,
  status VARCHAR(20) NOT NULL, view_count INTEGER NOT NULL DEFAULT 0,
  helpful_count INTEGER NOT NULL DEFAULT 0, published_at TIMESTAMPTZ
);
CREATE TABLE notifications (
  notification_id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users,
  channel VARCHAR(20) NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL,
  sent_at TIMESTAMPTZ, delivery_status VARCHAR(20) NOT NULL
);
CREATE TABLE audit_logs (
  audit_id BIGSERIAL PRIMARY KEY, actor_user_id BIGINT REFERENCES users,
  entity_type VARCHAR(50) NOT NULL, entity_id BIGINT NOT NULL,
  action VARCHAR(40) NOT NULL, old_values JSONB, new_values JSONB,
  occurred_at TIMESTAMPTZ NOT NULL, source_ip INET
);

CREATE INDEX idx_incidents_created ON incidents(created_at);
CREATE INDEX idx_incidents_status_priority ON incidents(status_id,priority_id);
CREATE INDEX idx_incidents_team_created ON incidents(assigned_team_id,created_at);
CREATE INDEX idx_incidents_requester ON incidents(requester_id);
CREATE INDEX idx_comments_incident_created ON incident_comments(incident_id,created_at);
CREATE INDEX idx_audit_entity ON audit_logs(entity_type,entity_id,occurred_at);
CREATE INDEX idx_assets_assigned_user ON assets(assigned_user_id);
COMMIT;

SET search_path TO esmp;
UPDATE teams SET manager_user_id = CASE team_id WHEN 1 THEN 2 WHEN 2 THEN 3 WHEN 3 THEN 4 WHEN 4 THEN 5 WHEN 5 THEN 6 WHEN 6 THEN 7 WHEN 7 THEN 8 ELSE 9 END;

-- End of synthetic dataset.
